#include <stdlib.h>#include "mesh.h"#include "mesh.h"#include "256.h"#include "FileStuff.h"#include "BMP.h"void reverse(char *, int);void SpinCursor( int initFlag );Boolean CommandPeriod ( void );OSErr putTexture ( Str255 thePlugFileName, meshHeader theMeshHeader );OSErr putTexture ( Str255 thePlugFileName, meshHeader theMeshHeader ){//----------------------------------vars--------------------------------------------------	short		thePlugFileRef;	OSErr		theError;	FSSpec		thePlugFSSpec;	int i, x, y, theMark;	char	*theTexture;	long	theSize, theWidth, theHeight;	int		theMeshSize;									// in sections	struct sectionInfoEntry *sectionInfo;	int redAverage, greenAverage, blueAverage, curColorDiff, colorDiff;	int redDiff, greenDiff, blueDiff;	char colorMapByte;	Myth256Palette thePalette;	 _256Header thePlugHeader; //----------------------------------------------------------------------------------------	// new plug file	theError = FSMakeFSSpec (0L, 0L, thePlugFileName, &thePlugFSSpec);	if ( theError != noErr )		return theError;	theError = FSpOpenDF ( &thePlugFSSpec, fsCurPerm, &thePlugFileRef );	if ( theError != noErr )		return theError;	theMeshSize = theMeshHeader.meshWidth * theMeshHeader.meshHeight;	theWidth = theMeshHeader.meshWidth * 256;	theHeight = theMeshHeader.meshHeight * 256;	theSize = theWidth * theHeight;	FileRead ( &thePlugHeader, sizeof( _256Header ), thePlugFileRef );	thePlugHeader.sectionInfoOffset += sizeof(struct _256Header);			// add header length to offset	thePlugHeader.paletteOffset += sizeof(struct _256Header);				// ditto	thePlugHeader.colorMapOffset += sizeof(struct _256Header);	sectionInfo = (struct sectionInfoEntry *) NewPtr ( thePlugHeader.sections * sizeof(sectionInfoEntry) );	if ( sectionInfo == nil ){		FSClose ( thePlugFileRef );		return -1;	}	theTexture = (char *) NewPtr (theSize);	if ( theTexture == nil ){		DisposePtr ( (char *) sectionInfo );		FSClose ( thePlugFileRef );		return -1;	}	FileSeek ( thePlugFileRef, thePlugHeader.sectionInfoOffset );	FileRead (sectionInfo, 128 * thePlugHeader.sections, thePlugFileRef );	for( i = 0; i < thePlugHeader.sections; i++ )		sectionInfo[i].offset += (sizeof(struct _256Header) + sizeof(struct textureHeader));	FileSeek ( thePlugFileRef, thePlugHeader.paletteOffset );	FileRead ( &thePalette, sizeof(Myth256Palette), thePlugFileRef );	theError = readBMP ( "\p:Graphics.in:texture.bmp", theWidth, theHeight, &thePalette, theTexture );	if ( theError != noErr ){		DisposePtr ( (Ptr) theTexture );		DisposePtr ( (Ptr) sectionInfo );		FSClose ( thePlugFileRef );		return theError;	}	FileSeek ( thePlugFileRef, thePlugHeader.paletteOffset );	FileWrite ( &thePalette, sizeof (Myth256Palette), thePlugFileRef );	SpinCursor ( true );	theMark = 0;	for( y = 0; y < 2 * theMeshSize - theMeshHeader.meshWidth; y += (2 * theMeshHeader.meshWidth) ){ // sections y		for(i = 0; i < 256; i++){	// get one line from each section across			if ( CommandPeriod() ){				DisposePtr ( (char *) sectionInfo );				DisposePtr ( theTexture );				FSClose ( thePlugFileRef );				InitCursor();				return noErr; 			}			SpinCursor ( false );			for( x = (2 * theMeshHeader.meshWidth - 2); x >= 0; x -= 2 ){	// sections x				FileSeek ( thePlugFileRef, sectionInfo[x + y].offset + (i * 256) );				reverse(theTexture + theMark, 256);				FileWrite (theTexture + theMark, 256, thePlugFileRef);				theMark += 256;			}		}	}	FileSeek ( thePlugFileRef, thePlugHeader.colorMapOffset );	for ( x = 0; x < 256; x++ )							//first write the first line-- not averaged		FilePutChar ( x, thePlugFileRef );	for(y = 1; y < 256; y++){							//then go through the rest of the bytes		FilePutChar ( y, thePlugFileRef );				//write the first column-- not averaged				for(x = 1; x < 256; x++){ 			redAverage = (thePalette.color[x].red + thePalette.color[y].red) / 2; 			greenAverage = (thePalette.color[x].green + thePalette.color[y].green) / 2; 			blueAverage = (thePalette.color[x].blue + thePalette.color[y].blue) / 2;			colorMapByte = 0;			curColorDiff = 0x1000000;						for(i = 255; i >= 0; i--){						//find the closest palette pixel				redDiff = abs( redAverage - thePalette.color[i].red );				greenDiff = abs( greenAverage - thePalette.color[i].green );				blueDiff = abs( blueAverage - thePalette.color[i].blue );								colorDiff =  	redDiff * redDiff +							 	greenDiff * greenDiff +								blueDiff * blueDiff;												if (colorDiff < curColorDiff) {					curColorDiff = colorDiff;					colorMapByte = i;				}				if (curColorDiff == 0)					break;			}			FilePutChar ( colorMapByte, thePlugFileRef );		}	}		DisposePtr ( (char *) sectionInfo );	DisposePtr ( theTexture );	FSClose ( thePlugFileRef );	InitCursor();	return	noErr;}